from base.exceptions import EntityBadRequestError, InsufficientPermissionsErrorfrom base.service import BaseServicefrom models.container import Containerfrom models.container import ContainerType as ctfrom models.topic_offer import TopicOffer, TopicOfferStatusfrom repositories.container import ContainerRepositoryfrom schemas.topic import AddTopicByOffer, CreateTopicfrom services.container import ContainerServicefrom services.topic_offer import TopicOfferServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom user import Userfrom utils.post import generate_slugclass TopicService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.offer_service = TopicOfferService(session)        self.container_service = ContainerService(session)    async def create_topic(            self,            topic: CreateTopic,            author: User,            from_offer: bool = False    ) -> Container:        if author.role < UserRoleEnum.MODERATOR and not from_offer:            raise InsufficientPermissionsError()        topic.slug = generate_slug(topic.slug)        await self.check_already_exists(slug=topic.slug, type=ct.topic)        topic = await self.container_service.create_item(            **topic.dict(),            type=ct.topic,            author_id=author.id        )        return topic    async def create_topic_from_offer(            self,            topic_offer: TopicOffer,            process: AddTopicByOffer,            process_user: User    ) -> TopicOffer:        if topic_offer.status != TopicOfferStatus.PENDING:            raise EntityBadRequestError(                "offer-Тема", f"Предложенная тема уже имеет статус {topic_offer.status}"            )        await self.offer_service.update_item(            topic_offer,            status=process.status,            process_user_id=process_user.id        )        if process.status == TopicOfferStatus.APPROVE:            slug = generate_slug(process.slug)            title = process.title or topic_offer.title            description = process.description or topic_offer.description            topic = CreateTopic(                title=title,                description=description,                slug=slug            )            release_topic = await self.create_topic(                topic=topic, author=topic_offer.author, from_offer=True            )            await self.offer_service.update_item(                topic_offer,                release_topic_id=release_topic.id            )        return topic_offer